private static void Advance(Body[] bodies, double dt) {
    for (int i = 0; i < bodies.Length; i++) {
        Body bi = bodies[i];
        for (int j = i + 1; j < bodies.Length; j++) {
            Body bj = bodies[j];
            double dx = bi.x - bj.x;
            double dy = bi.y - bj.y;
            double dz = bi.z - bj.z;

            double d2 = dx * dx + dy * dy + dz * dz;
